def g(s, t):
    r = len(s)
    p = len(t)
    i = 0
    while i <= len(s) - p:
        u = 0
        if s[i] == t[0]:
            for j in range(1, p):
                if s[i + j] != t[j]:
                    u = 1
                    i += 1
                    break
            if not u:
                i += p
                r -= p - 1
        else:
            i += 1
    return r

